use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let mut fields: Vec<string> = []
        let mut cur = ""
        let mut inq = false
        let mut pending_quote = false
        for c in line.chars() {
            if inq {
                if pending_quote {
                    if c == '"' {
                        cur = cur + "\""
                        pending_quote = false
                    } else {
                        inq = false
                        pending_quote = false
                        if c == ',' {
                            fields.push(cur)
                            cur = ""
                        } else {
                            cur = cur + c.to_string()
                        }
                    }
                } else if c == '"' {
                    pending_quote = true
                } else {
                    cur = cur + c.to_string()
                }
            } else if c == '"' {
                inq = true
            } else if c == ',' {
                fields.push(cur)
                cur = ""
            } else {
                cur = cur + c.to_string()
            }
        }
        fields.push(cur)
        let mut out = ""
        let mut i = 0
        for f in fields {
            if i > 0 {
                out = out + "|"
            }
            out = out + "[" + f + "]"
            i += 1
        }
        println("${i}: ${out}")
    }
}

